        { id: 1, type: "New", description: "Initial ticket", priority: "Low", assignedTo: 1, created: new Date(), updated: new Date() },
        { id: 2, type: "Feature", description: "Add feature to our product", priority: "Low", assignedTo: 1, created: new Date(), updated: new Date() },
        // weitere Tickets...
